1	// lantern — small progressive enhancements shared by all pages. No dependencies.
2	(function () {
3	  "use strict";
4	
5	  // Copy button on every code block. navigator.clipboard only exists in secure
6	  // contexts (https / localhost); over plain http on the LAN fall back to execCommand.
7	  function copyText(text) {
8	    if (navigator.clipboard && window.isSecureContext) {
9	      return navigator.clipboard.writeText(text);
10	    }
11	    return new Promise(function (resolve, reject) {
12	      var ta = document.createElement("textarea");
13	      ta.value = text;
14	      ta.setAttribute("readonly", "");
15	      ta.style.position = "fixed";
16	      ta.style.opacity = "0";
17	      document.body.appendChild(ta);
18	      ta.select();
19	      var ok = false;
20	      try { ok = document.execCommand("copy"); } catch (e) { /* ignore */ }
21	      document.body.removeChild(ta);
22	      ok ? resolve() : reject(new Error("copy failed"));
23	    });
24	  }
25	
26	  function addCopyButtons() {
27	    document.querySelectorAll("pre").forEach(function (pre) {
28	      if (pre.classList.contains("mermaid") || pre.querySelector(".copy-btn")) return;
29	      var btn = document.createElement("button");
30	      btn.type = "button";
31	      btn.className = "copy-btn";
32	      btn.textContent = "Copy";
33	      btn.addEventListener("click", function () {
34	        var code = pre.querySelector("code") || pre;
35	        copyText(code.innerText.replace(/\n$/, "")).then(
36	          function () { flash(btn, "Copied"); },
37	          function () { flash(btn, "Press Ctrl+C"); selectNode(code); }
38	        );
39	      });
40	      pre.appendChild(btn);
41	    });
42	  }
43	
44	  function flash(btn, text) {
45	    btn.textContent = text;
46	    btn.classList.add("done");
47	    setTimeout(function () { btn.textContent = "Copy"; btn.classList.remove("done"); }, 1500);
48	  }
49	
50	  function selectNode(node) {
51	    var range = document.createRange();
52	    range.selectNodeContents(node);
53	    var sel = window.getSelection();
54	    sel.removeAllRanges();
55	    sel.addRange(range);
56	  }
57	
58	  // Hover "#" links on headings that have ids (Caddy's markdown adds them).
59	  function addAnchors() {
60	    document.querySelectorAll(".doc :is(h1, h2, h3, h4)[id]").forEach(function (h) {
61	      var a = document.createElement("a");
62	      a.className = "anchor";
63	      a.href = "#" + h.id;
64	      a.setAttribute("aria-label", "Link to this section");
65	      a.textContent = "#";
66	      h.prepend(a);
67	    });
68	  }
69	
70	  // ```mermaid blocks -> diagrams, only when the page loaded vendor/mermaid.min.js.
71	  function renderMermaid() {
72	    if (!window.mermaid) return;
73	    var blocks = document.querySelectorAll("pre > code.language-mermaid");
74	    if (!blocks.length) return;
75	    blocks.forEach(function (code) {
76	      var pre = document.createElement("pre");
77	      pre.className = "mermaid";
78	      pre.textContent = code.textContent;
79	      code.parentNode.replaceWith(pre);
80	    });
81	    var dark = window.matchMedia("(prefers-color-scheme: dark)").matches;
82	    window.mermaid.initialize({ startOnLoad: false, theme: dark ? "dark" : "default" });
83	    window.mermaid.run({ querySelector: "pre.mermaid" });
84	  }
85	
86	  // Elements with data-app-status="/name/" get an up/down badge. A reverse proxy
87	  // with nothing behind it answers 502, so any status below 500 means "up".
88	  function checkApps() {
89	    document.querySelectorAll("[data-app-status]").forEach(function (el) {
90	      fetch(el.getAttribute("data-app-status"), { method: "HEAD", cache: "no-store", redirect: "manual" })
91	        .then(function (r) { return r.type === "opaqueredirect" || r.status < 500; })
92	        .catch(function () { return false; })
93	        .then(function (up) {
94	          el.textContent = up ? "up" : "down";
95	          el.className = "badge " + (up ? "up" : "down");
96	        });
97	    });
98	  }
99	
100	  // <time datetime> elements (directory listings) are rendered in UTC; show local time.
101	  function localTimes() {
102	    document.querySelectorAll("time[datetime]").forEach(function (t) {
103	      var d = new Date(t.getAttribute("datetime"));
104	      if (isNaN(d)) return;
105	      var pad = function (n) { return String(n).padStart(2, "0"); };
106	      t.textContent = d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate()) +
107	        " " + pad(d.getHours()) + ":" + pad(d.getMinutes());
108	      t.title = d.toString();
109	    });
110	  }
111	
112	  function init() {
113	    renderMermaid();
114	    addCopyButtons();
115	    addAnchors();
116	    checkApps();
117	    localTimes();
118	  }
119	
120	  if (document.readyState === "loading") {
121	    document.addEventListener("DOMContentLoaded", init);
122	  } else {
123	    init();
124	  }
125	})();
