1	# lantern — written once. Adding a doc or an app must never require editing this file.
2	#
3	# Env (set by the systemd unit and by bin/lantern):
4	#   LANTERN_ROOT  absolute path of this repo (required)
5	#   LANTERN_PORT  listen port (default 8080)
6	#
7	# Everything below runs inside one `route` so the order is exactly as written:
8	# first match wins, top to bottom.
9	{
10		# Plain HTTP on the LAN: no certificates, no redirects to https.
11		auto_https off
12		admin localhost:{$LANTERN_ADMIN_PORT:2019}
13	}
14	
15	# Routing for one app. apps/<name>/route.caddy normally contains just:
16	#     import lantern-app <name> <port>
17	# The /<name> prefix is stripped before proxying; the app gets it back in
18	# X-Forwarded-Prefix in case it needs to build absolute URLs.
19	(lantern-app) {
20		redir /{args[0]} /{args[0]}/ 308
21		handle_path /{args[0]}/* {
22			reverse_proxy 127.0.0.1:{args[1]} {
23				header_up X-Forwarded-Prefix /{args[0]}
24			}
25		}
26	}
27	
28	# Same, but the /<name> prefix is kept: for apps that serve under a base path
29	# themselves (Streamlit --server.baseUrlPath, marimo --base-url, Dash url_base_pathname).
30	#     import lantern-app-keep <name> <port>      (add-app --keep-prefix)
31	(lantern-app-keep) {
32		redir /{args[0]} /{args[0]}/ 308
33		handle /{args[0]}/* {
34			reverse_proxy 127.0.0.1:{args[1]} {
35				header_up X-Forwarded-Prefix /{args[0]}
36			}
37		}
38	}
39	
40	http://:{$LANTERN_PORT:8080} {
41		encode zstd gzip
42	
43		route {
44			# 1. Never serve hidden or junk paths from symlinked repos (.git, .env, …).
45			@hidden path_regexp (^|/)(\.|node_modules(/|$)|__pycache__(/|$))
46			error @hidden 404
47	
48			# 2. Apps (one route.caddy per app; zero apps is fine).
49			import {$LANTERN_ROOT}/apps/*/route.caddy
50	
51			# 3. Shared styles, scripts and templates.
52			handle_path /_shared/* {
53				root * {$LANTERN_ROOT}/_shared
54				file_server
55			}
56	
57			# 4. Landing page: lists sites/ and apps/ on every request.
58			handle / {
59				root * {$LANTERN_ROOT}
60				rewrite * /_shared/index.html
61				templates
62				file_server
63			}
64	
65			# 5. Docs.
66			handle {
67				root * {$LANTERN_ROOT}/sites
68	
69				# A directory's README.md is its index page (an index.html still wins).
70				@readme {
71					path */
72					not file {path}index.html
73					file {path}README.md {path}readme.md {path}index.md
74				}
75				rewrite @readme {file_match.relative}
76	
77				# Markdown → HTML. The template reads the post-rewrite path from a
78				# server-side var, so it can't be spoofed via the query string.
79				@markdown {
80					path *.md *.markdown
81					file
82				}
83				handle @markdown {
84					vars lantern_doc {path}
85					root * {$LANTERN_ROOT}/_shared
86					rewrite * /md.html
87					templates {
88						root {$LANTERN_ROOT}/sites
89					}
90					file_server
91				}
92	
93				# Everything else as-is; directories without a README get a listing.
94				handle {
95					file_server {
96						browse {$LANTERN_ROOT}/_shared/browse.html
97						hide .* node_modules __pycache__
98					}
99				}
100			}
101		}
102	
103		handle_errors {
104			root * {$LANTERN_ROOT}/_shared
105			rewrite * /error.html
106			templates
107			file_server
108		}
109	}
110

1	{{- /*
2	  Landing page. Lists sites/ and apps/ on every request, so it is always current.
3	  Template root is LANTERN_ROOT. Titles come from a README's frontmatter `title`
4	  or its leading `# heading`; parsed with regexes so one malformed README can't
5	  break this page.
6	*/ -}}
7	{{- define "card" -}}
8	  {{- $name := .name -}}{{- $dir := .dir -}}
9	  {{- $ok := fileExists $dir -}}
10	  {{- $readme := "" -}}
11	  {{- if $ok}}{{range list "README.md" "readme.md" "index.md"}}{{if and (not $readme) (fileExists (printf "%s/%s" $dir .))}}{{$readme = printf "%s/%s" $dir .}}{{end}}{{end}}{{end -}}
12	  {{- $title := $name -}}{{- $desc := "" -}}
13	  {{- if $readme -}}
14	    {{- $src := readFile $readme -}}
15	    {{- $fm := regexFind `^---\r?\n(?s:.*?)\r?\n---` $src -}}
16	    {{- $t := regexFind `(?m)^title:[ \t]*\S.*$` $fm -}}
17	    {{- $h1 := regexFind `^\s*#[ \t]+[^\n]+` (trimPrefix $fm $src) -}}
18	    {{- if $t}}{{$title = trimAll `"' ` (trimPrefix "title:" $t)}}
19	    {{- else if $h1}}{{$title = trim (regexReplaceAll `^\s*#[ \t]+|[ \t]+#+[ \t]*$` $h1 "")}}{{end -}}
20	    {{- $desc = trimAll `"' ` (trimPrefix "description:" (regexFind `(?m)^description:[ \t]*\S.*$` $fm)) -}}
21	  {{- end}}
22	  <li><a href="/{{html $name}}/">
23	    <div class="title">{{html $title}}
24	      {{- if not $ok}} <span class="badge broken">broken link</span>{{end}}
25	      {{- if .app}} <span class="badge" data-app-status="/{{html $name}}/">…</span>{{end}}</div>
26	    <div class="path">/{{html $name}}/</div>
27	    {{- with $desc}}
28	    <div class="desc">{{html .}}</div>
29	    {{- end}}
30	  </a></li>
31	{{- end -}}
32	
33	{{- $sites := list -}}
34	{{- range listFiles "/sites"}}{{if not (hasPrefix "." .)}}{{$sites = append $sites .}}{{end}}{{end -}}
35	{{- $apps := list -}}
36	{{- range listFiles "/apps"}}{{if and (not (hasPrefix "." .)) (fileExists (printf "/apps/%s/route.caddy" .))}}{{$apps = append $apps .}}{{end}}{{end -}}
37	
38	<!doctype html>
39	<html lang="en">
40	<head>
41	<meta charset="utf-8">
42	<meta name="viewport" content="width=device-width, initial-scale=1">
43	<title>lantern · {{.Host}} by MHZ</title>
44	<link rel="stylesheet" href="/_shared/style.css">
45	<script defer src="/_shared/lantern.js"></script>
46	</head>
47	<body>
48	<header class="lantern-bar">
49	  <nav class="crumbs"><a class="home" href="/">lantern</a> by <a href="https://github.com/kiswelrg/" target="_blank">HZ Mei</a></nav>
50	</header>
51	<main class="page">
52	<h1>Docs &amp; tools on {{.Host}}</h1>
53	<p class="lead">Docs, READMEs, showcases and small tools from various repos.</p>
54	<p class="lead">Ctrl+F to quickly locate contents on page.</p>
55	
56	<h2>Docs</h2>
57	{{- if $sites}}
58	<ul class="cards">
59	{{- range $sites}}
60	  {{template "card" (dict "name" . "dir" (printf "/sites/%s" .))}}
61	{{- end}}
62	</ul>
63	{{- else}}
64	<p class="empty">Nothing yet. Add one with <code>bin/lantern add-site &lt;name&gt; &lt;path&gt;</code>.</p>
65	{{- end}}
66	
67	<h2>Apps</h2>
68	{{- if $apps}}
69	<ul class="cards">
70	{{- range $apps}}
71	  {{template "card" (dict "name" . "dir" (printf "/apps/%s" .) "app" true)}}
72	{{- end}}
73	</ul>
74	{{- else}}
75	<p class="empty">No apps. Add one with <code>bin/lantern add-app &lt;name&gt;</code>.</p>
76	{{- end}}
77	</main>
78	</body>
79	</html>
80

