# Routing for one app. apps/<name>/route.caddy normally contains one import line,
# written by bin/lantern. The upstream is 127.0.0.1:<port> for an app lantern runs
# (a server or an ssh tunnel), or <host>:<port> for a service elsewhere (add-proxy).
#
#     import lantern-app <name> <port>
#     import lantern-proxy <name> <host>:<port>
# The /<name> prefix is stripped before proxying; the app gets it back in
# X-Forwarded-Prefix in case it needs to build absolute URLs.
(lantern-proxy) {
	redir /{args[0]} /{args[0]}/ 308
	handle_path /{args[0]}/* {
		reverse_proxy {args[1]} {
			header_up X-Forwarded-Prefix /{args[0]}
		}
	}
}
(lantern-app) {
	import lantern-proxy {args[0]} 127.0.0.1:{args[1]}
}

# Same, but the /<name> prefix is kept: for apps that serve under a base path
# themselves (Streamlit --server.baseUrlPath, marimo --base-url, Dash url_base_pathname).
#     import lantern-app-keep <name> <port>               (--keep-prefix)
#     import lantern-proxy-keep <name> <host>:<port>
(lantern-proxy-keep) {
	redir /{args[0]} /{args[0]}/ 308
	handle /{args[0]}/* {
		reverse_proxy {args[1]} {
			header_up X-Forwarded-Prefix /{args[0]}
		}
	}
}
(lantern-app-keep) {
	import lantern-proxy-keep {args[0]} 127.0.0.1:{args[1]}
}

# An app on its own LAN port (--own-port), for apps that need to own "/" (absolute
# URLs they can't be told about: device UIs, vendor dashboards). Two files:
#   apps/<name>/port.caddy   import lantern-own-port-site <name> <lan-port> <upstream>
#   apps/<name>/route.caddy  import lantern-own-port <name> <lan-port> <upstream>
# The first is the app's own site; the second keeps /<name>/ on the main port as a
# redirect to it, plus HEAD /_status/<name> for the landing page's up/down badge
# (a request to another port is cross-origin, so the page can't read its status).
(lantern-own-port-site) {
	http://:{args[1]} {
		reverse_proxy {args[2]}
		handle_errors {
			# error.html links styles and home through the main port; here "/" is the app's.
			vars lantern_home http://{host}:{$LANTERN_PORT:8080}
			root * {$LANTERN_ROOT}/_shared
			rewrite * /error.html
			templates
			file_server
		}
	}
}
(lantern-own-port) {
	redir /{args[0]} http://{host}:{args[1]}/ 302
	redir /{args[0]}/* http://{host}:{args[1]}/ 302
	@status-{args[0]} {
		method HEAD
		path /_status/{args[0]}
	}
	handle @status-{args[0]} {
		rewrite * /
		reverse_proxy {args[2]}
	}
}

