  {{- $lan = trimPrefix "LAN_PORT=" (regexFind `(?m)^LAN_PORT=[0-9]+` $env) -}}
  {{- $tunnel = trimPrefix "TUNNEL_TO=" (regexFind `(?m)^TUNNEL_TO=\S+` $env) -}}
  {{- $upstream = trimPrefix "UPSTREAM=" (regexFind `(?m)^UPSTREAM=\S+` $env) -}}
{{- end -}}
{{- /* An app on its own port is linked there directly; its badge asks /_status/<name>. */ -}}
{{- $href := printf "/%s/" $name -}}{{- $path := $href -}}{{- $status := $href -}}
{{- if $lan}}{{$href = printf "http://%s:%s/" .host $lan}}{{$path = printf ":%s/" $lan}}{{$status = printf "/_status/%s" $name}}{{end}}
<li><a href="{{html $href}}">
  <div class="title">{{html $title}}
    {{- if not $ok}} <span class="badge broken">broken link</span>{{end}}
    {{- if .app}} <span class="badge" data-app-status="{{html $status}}">…</span>{{end}}</div>
  <div class="path">{{html $path}}
    {{- if $tunnel}} <span class="dot tunnel" title="ssh tunnel to {{html $tunnel}}"></span>
    {{- else if $upstream}} <span class="dot remote" title="proxied from {{html $upstream}}"></span>{{end}}</div>

{{- range listFiles "/apps"}}{{if and (not (hasPrefix "." .)) (fileExists (printf "/apps/%s/route.caddy" .))}}{{$apps = append $apps .}}{{end}}{{end -}}
{{- /* Which dots the legend explains: only those some card shows. */ -}}
{{- $tunnels := false -}}{{- $remotes := false -}}
{{- range $apps}}{{$f := printf "/apps/%s/app.env" .}}{{if fileExists $f}}{{$e := readFile $f}}
  {{- if regexMatch `(?m)^TUNNEL_TO=\S` $e}}{{$tunnels = true}}{{else if regexMatch `(?m)^UPSTREAM=\S` $e}}{{$remotes = true}}{{end}}
{{- end}}{{end -}}

