input.command:
python3 - <<'PY'
p='Caddyfile'
s=open(p).read()
start=s.index('# Routing for one app. apps/<name>/route.caddy normally contains one import line,')
end=s.index('# Apps on their own port (one port.caddy per such app; zero is fine).')
new='''# Routing for one app. apps/<name>/route.caddy (and port.caddy, for an app on its own
# port) holds one import line written by bin/lantern: lantern-app* for an app lantern runs
# on 127.0.0.1:<port> (a server or an ssh tunnel), lantern-proxy* for a service elsewhere.
#
#   import lantern-app <name> <port>          import lantern-proxy <name> <host>:<port>
#     At /<name>/. The prefix is stripped before proxying; the app gets it back in
#     X-Forwarded-Prefix in case it needs to build absolute URLs.
#   import lantern-app-keep <name> <port>     import lantern-proxy-keep <name> <host>:<port>
#     Same, prefix kept (--keep-prefix): for apps that serve under a base path themselves
#     (Streamlit --server.baseUrlPath, marimo --base-url, Dash url_base_pathname).
#   import lantern-app-own-port[-site] <name> <lan-port> <port>
#   import lantern-proxy-own-port[-site] <name> <lan-port> <host>:<port>
#     At the root of the app's own LAN port (--own-port), for apps that need "/" (absolute
#     URLs they can't be told about: device UIs, vendor dashboards). The -site import, in
#     port.caddy, is that port's site; the other, in route.caddy, redirects /<name>/ there
#     and answers HEAD /_status/<name> for the landing page's up/down badge (a request to
#     another port is cross-origin, so the page can't read its status).
#
# A local app gets the visitor's Host header, so URLs it builds point back at lantern. A
# service elsewhere gets its own: forward proxies (HTTP_PROXY in lantern.env) and virtual
# hosts route by it, and with the visitor's Host a proxy sends the request back here.
(lantern-to-path) {
	# name, upstream, Host for the upstream
	redir /{args[0]} /{args[0]}/ 308
	handle_path /{args[0]}/* {
		reverse_proxy {args[1]} {
			header_up Host {args[2]}
			header_up X-Forwarded-Prefix /{args[0]}
		}
	}
}
(lantern-to-path-keep) {
	redir /{args[0]} /{args[0]}/ 308
	handle /{args[0]}/* {
		reverse_proxy {args[1]} {
			header_up Host {args[2]}
			header_up X-Forwarded-Prefix /{args[0]}
		}
	}
}
(lantern-to-own-port) {
	# name, lan port, upstream, Host for the upstream
	redir /{args[0]} http://{host}:{args[1]}/ 302
	redir /{args[0]}/* http://{host}:{args[1]}/ 302
	@status-{args[0]} {
		method HEAD
		path /_status/{args[0]}
	}
	handle @status-{args[0]} {
		rewrite * /
		reverse_proxy {args[2]} {
			header_up Host {args[3]}
		}
	}
}
(lantern-to-own-port-site) {
	http://:{args[1]} {
		reverse_proxy {args[2]} {
			header_up Host {args[3]}
		}
		handle_errors {
			# error.html links styles and home through the main port; here "/" is the app's.
			vars lantern_home http://{host}:{$LANTERN_PORT:8080}
			root * {$LANTERN_ROOT}/_shared
			rewrite * /error.html
			templates
			file_server
		}
	}
}
(lantern-app) {
	import lantern-to-path {args[0]} 127.0.0.1:{args[1]} {hostport}
}
(lantern-app-keep) {
	import lantern-to-path-keep {args[0]} 127.0.0.1:{args[1]} {hostport}
}
(lantern-app-own-port) {
	import lantern-to-own-port {args[0]} {args[1]} 127.0.0.1:{args[2]} {hostport}
}
(lantern-app-own-port-site) {
	import lantern-to-own-port-site {args[0]} {args[1]} 127.0.0.1:{args[2]} {hostport}
}
(lantern-proxy) {
	import lantern-to-path {args[0]} {args[1]} {upstream_hostport}
}
(lantern-proxy-keep) {
	import lantern-to-path-keep {args[0]} {args[1]} {upstream_hostport}
}
(lantern-proxy-own-port) {
	import lantern-to-own-port {args[0]} {args[1]} {args[2]} {upstream_hostport}
